"""Apply Amlak customizations to the fresh android/ folder generated by
`flutter create` on the CI runner. Idempotent: safe to run multiple times."""
import pathlib
import re

manifest = pathlib.Path("android/app/src/main/AndroidManifest.xml")
text = manifest.read_text(encoding="utf-8")

perms = [
    '<uses-permission android:name="android.permission.INTERNET"/>',
    '<uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/>',
    '<uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>',
    '<uses-permission android:name="android.permission.CALL_PHONE"/>',
    '<uses-permission android:name="android.permission.READ_MEDIA_IMAGES"/>',
    '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32"/>',
]
for p in perms:
    if p not in text:
        text = text.replace("<application", p + "\n    <application", 1)

text = re.sub(r'android:label="[^"]*"', 'android:label="املاک"', text, count=1)

queries = """    <queries>
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL" />
            <data android:scheme="tel" />
        </intent>
    </queries>
"""
if "<queries>" not in text:
    text = text.replace("</manifest>", queries + "</manifest>", 1)

manifest.write_text(text, encoding="utf-8")
print("patched OK")
